public interface IButton { string Render(); }
public interface IMenu { string Open(); }

public interface IUIFactory
{
    IButton CreateButton();
    IMenu CreateMenu();
}

// Family: dark theme
public sealed class DarkButton : IButton { public string Render() => "[dark button]"; }
public sealed class DarkMenu : IMenu { public string Open() => "{dark menu}"; }
public sealed class DarkFactory : IUIFactory
{
    public IButton CreateButton() => new DarkButton();
    public IMenu CreateMenu() => new DarkMenu();
}

// Family: light theme
public sealed class LightButton : IButton { public string Render() => "[light button]"; }
public sealed class LightMenu : IMenu { public string Open() => "{light menu}"; }
public sealed class LightFactory : IUIFactory
{
    public IButton CreateButton() => new LightButton();
    public IMenu CreateMenu() => new LightMenu();
}

public static class Demo
{
    public static string Run(IUIFactory factory)
    {
        var button = factory.CreateButton();
        var menu = factory.CreateMenu();
        return $"{button.Render()} {menu.Open()}";
    }
}

// Console.WriteLine(Demo.Run(new DarkFactory())); // [dark button] {dark menu}

public interface ILogger
{
    void Log(string message);
    IReadOnlyList<string> Entries { get; }
}

// Legacy SDK with an awkward API (cannot be changed)
public sealed class OldLogSdk
{
    private readonly List<string> _lines = [];
    public void WriteLine(string message, int level) => _lines.Add($"L{level}: {message}");
    public IReadOnlyList<string> Dump() => _lines;
}

public sealed class LegacyLoggerAdapter : ILogger
{
    private readonly OldLogSdk _legacy = new();

    public void Log(string message) => _legacy.WriteLine(message, level: 1);

    public IReadOnlyList<string> Entries => _legacy.Dump();
}

public static class Demo
{
    public static string Run()
    {
        ILogger logger = new LegacyLoggerAdapter();
        logger.Log("hello");
        return string.Join("|", logger.Entries); // "L1: hello"
    }
}

// Console.WriteLine(Demo.Run()); // L1: hello

public interface ISortStrategy
{
    int[] Sort(int[] data);
}

public sealed class AscendingStrategy : ISortStrategy
{
    public int[] Sort(int[] data) => [.. data.OrderBy(x => x)];
}

public sealed class DescendingStrategy : ISortStrategy
{
    public int[] Sort(int[] data) => [.. data.OrderByDescending(x => x)];
}

public sealed class Sorter(ISortStrategy strategy)
{
    public int[] Run(int[] data) => strategy.Sort(data);
}

public static class Demo
{
    public static int[] Run(int[] data, bool desc)
    {
        ISortStrategy strategy = desc ? new DescendingStrategy() : new AscendingStrategy();
        return new Sorter(strategy).Run(data);
    }
}

// Demo.Run([3,1,2], desc: false) -> [1,2,3]
